from pathlib import Path
import base64,gzip,hashlib,json,shutil,subprocess,sys,zipfile

ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
OUT=HERE/'out'
PKG=OUT/'SpotifyControl-v0.6.21-r10-Runtime-Acceptance-v1.0.0'
ZIP=OUT/'SpotifyControl-v0.6.21-r10-Runtime-Acceptance-v1.0.0.zip'
CANDIDATE=ROOT/'validation/v0.6.21/out/bin/addon-manager.ps1'
EXPECTED_SHA='7991b8eaa5a943957aebb9d3dd84d455ed6266430da442a672c05c145fe497a2'
EXPECTED_SIZE=250616
RELEASE_HEAD='5eac4f39920b84f22e2a5ee07422f6080bfc7ef7'
VALIDATION_HEAD='248dcd5315cd98cb798b0b711d21f50355c65d1d'
EMBEDDED_GZIP_B64={'RUN_RUNTIME_ACCEPTANCE.ps1': '', 'PRECHECK_RUNTIME_ACCEPTANCE.ps1': '', 'RUN_RUNTIME_ACCEPTANCE.cmd': '', 'README.txt': '', 'validate_package.py': ''}

def sha_bytes(b): return hashlib.sha256(b).hexdigest()
def sha_file(p): return sha_bytes(p.read_bytes())
def embedded_bytes(name): return gzip.decompress(base64.b64decode(EMBEDDED_GZIP_B64[name]))
def write_deterministic_zip(src,dst):
    if dst.exists(): dst.unlink()
    with zipfile.ZipFile(dst,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for p in sorted(x for x in src.rglob('*') if x.is_file()):
            rel=p.relative_to(src).as_posix(); data=p.read_bytes()
            info=zipfile.ZipInfo(rel,(2020,1,1,0,0,0)); info.compress_type=zipfile.ZIP_DEFLATED; info.external_attr=(0o100644<<16)
            z.writestr(info,data)

subprocess.check_call([sys.executable,str(ROOT/'validation/v0.6.21/build_v0621.py'),'--build'],cwd=ROOT)
assert CANDIDATE.is_file()
assert (CANDIDATE.stat().st_size,sha_file(CANDIDATE))==(EXPECTED_SIZE,EXPECTED_SHA)

shutil.rmtree(OUT,ignore_errors=True); PKG.mkdir(parents=True); (PKG/'candidate').mkdir(); (PKG/'evidence').mkdir()
for name in ['RUN_RUNTIME_ACCEPTANCE.ps1','PRECHECK_RUNTIME_ACCEPTANCE.ps1','RUN_RUNTIME_ACCEPTANCE.cmd','README.txt']:
    (PKG/name).write_bytes(embedded_bytes(name))
(PKG/'evidence'/'validate_package.py').write_bytes(embedded_bytes('validate_package.py'))
shutil.copy2(CANDIDATE,PKG/'candidate'/'addon-manager.ps1')
shutil.copy2(ROOT/'validation/v0.6.21/candidate-metadata.json',PKG/'evidence'/'candidate-metadata.json')
shutil.copy2(ROOT/'manifest.json',PKG/'evidence'/'release-manifest.json')
meta={
    'package_version':'1.0.0','purpose':'pre-release actual-machine read-only Addon Manager r10 acceptance',
    'release_head':RELEASE_HEAD,'candidate_validation_head':VALIDATION_HEAD,
    'production_main_version':'0.6.20','production_addon_version':'0.6.5-r9',
    'candidate_addon_version':'0.6.5-r10','candidate_addon_size':EXPECTED_SIZE,'candidate_addon_sha256':EXPECTED_SHA,
    'registry_sha256':'05c40a5339fe59b001ca0f4c4929643fd59e33a3002bae7067425845c85e2f6e',
    'allowed_runtime_actions':['SelfTest','Check -Force'],'mutating_runtime_actions':[],
    'success_leaves_production_version':'0.6.20/r9'
}
(PKG/'PACKAGE_METADATA.json').write_text(json.dumps(meta,indent=2),encoding='utf-8',newline='\n')
sum_files=['RUN_RUNTIME_ACCEPTANCE.ps1','PRECHECK_RUNTIME_ACCEPTANCE.ps1','RUN_RUNTIME_ACCEPTANCE.cmd','README.txt','PACKAGE_METADATA.json','candidate/addon-manager.ps1','evidence/validate_package.py','evidence/candidate-metadata.json','evidence/release-manifest.json']
(PKG/'SHA256SUMS.txt').write_text(''.join(f"{sha_file(PKG/rel)}  {rel}\n" for rel in sum_files),encoding='ascii',newline='\n')
res=subprocess.run([sys.executable,str(PKG/'evidence'/'validate_package.py')],text=True,capture_output=True)
(PKG/'evidence'/'VALIDATION_OUTPUT.txt').write_text(res.stdout+res.stderr,encoding='utf-8',newline='\n')
if res.returncode!=0: raise SystemExit(res.stdout+res.stderr)
write_deterministic_zip(PKG,ZIP)
with zipfile.ZipFile(ZIP) as z:
    assert z.testzip() is None
    assert z.read('candidate/addon-manager.ps1')==CANDIDATE.read_bytes()
print('V0621_R10_RUNTIME_ACCEPTANCE_BUILD_PASS',ZIP.stat().st_size,sha_file(ZIP),EXPECTED_SIZE,EXPECTED_SHA)
